stand_in_programs.ffmpeg:
last=""; for a in "$@"; do last="$a"; done
case " $* " in
  *" -filters "*) printf ' ... highpass A->A High-pass\n ... afftdn A->A Denoise\n' ;;
  *silencedetect*) echo 'silence_start: 0' >&2; echo 'silence_end: 1.0 | silence_duration: 1' >&2 ;;
  *" -af "*) printf 'RIFF' > "$last" ;;
  *) echo '  Duration: 00:00:04.00, start: 0.000000, bitrate: 256 kb/s' >&2; exit 1 ;;
esac
